g=dict(source_ids=ss,expectation_ids=['s-storage-contract'],binding_ids=binding,derivation='The direct Storage interface owes all-or-rollback on returned Err. Setup persists one entry and a promise, then the submitted batch queues a new promise and a good append before a final entry serializer returns a normal error. Public reads sample live cursor and database metadata; a following transaction changes only decided index, so failed promise/appends must remain absent. Reopen distinguishes persistent effects from live cursor alone.',applicability='One isolated persistent database, successful setup and ordinary I/O, no crashes or concurrency; Entry serialization can return Err through the implemented trait.',unresolved=[],conflicts=[],alternatives=['The database itself may remain unchanged at the initial Err even when the cursor changed; both are observed separately.','Dropping the object before reuse may discard pending writes; this check explicitly covers a live backend under its returned-error contract.'])
prereqs=[dict(alias='admitted',event='storage_admitted',conditions=[]),dict(alias='failed',event='storage_returned',conditions=[dict(field='op_id',reference='admitted.op_id'),dict(field='returned_error',value=True),dict(field='serialization_error_observed',value=True)]),dict(alias='later',event='independent_completed',conditions=[dict(field='op_id',reference='failed.op_id'),dict(field='success',value=True)])]
mon=[];props=[]
for check,event,field,expected in [('rollback-live-length','immediate_state','log_len','admitted.before_len'),('rollback-later-promise','after_independent','promise_n','admitted.before_promise_n')]:
 mon.append(dict(id='monitor-'+check,checker_id=check,event=event,binding_ids=binding,grounding=g,admission_alias='admitted',applicability_conditions=[]))
 props.append(dict(checker_id=check,kind='event_assertion',identity_fields=['op_id'],trigger=dict(field='event',value=event),assertion=dict(field=field,reference=expected),description='Failed write_atomically must preserve the corresponding pre-call observable; subsequent unrelated successful transaction must not publish failed writes.'))
# Later-transaction prerequisite is relevant only to the second monitor; use applicability? It would
