s=dict(action='check',unit_id='unit-claim-storage-error-rollback',rationale='Use a controlled entry serializer error to measure live state and delayed failed-transaction effects against the accepted Storage rollback contract.',plan_path='persistent-check-plan.json',harness_path='persistent_rollback.rs')
